import{_ as e,o as a,c as r,a2 as o}from"./chunks/framework.CHeM0PsO.js";const c=JSON.parse('{"title":"","description":"","frontmatter":{"layout":"home","hero":{"name":"AI 创意广告知识库","text":"把创意变成可复制的生产流程","tagline":"方法论、Prompt 模板、工具地图、案例拆解 —— 都是能直接抄走的东西","actions":[{"theme":"brand","text":"从这里开始","link":"/guide/"},{"theme":"alt","text":"直接抄 Prompt","link":"/prompts/structure"}]},"features":[{"title":"创意方法论","details":"从 brief 到成片的六阶段 SOP，哪一步交给 AI、哪一步必须人来把关，写得很清楚。","link":"/method/","linkText":"进入板块"},{"title":"Prompt 模板库","details":"按场景分类的可复制 Prompt，每条都标注适用场景、参数说明和常见翻车点。","link":"/prompts/","linkText":"进入板块"},{"title":"工具地图","details":"文案 / 图像 / 视频 / 配音 / 剪辑五类工具的定位对照，以及按预算选型的决策树。","link":"/tools/","linkText":"进入板块"},{"title":"实战流水线","details":"具体工具组合起来实际怎么跑 —— 目录结构、命名规范、哪一步能自动化、哪一步不能。","link":"/pipelines/","linkText":"进入板块"},{"title":"案例拆解","details":"统一的拆解格式：创意点 → 生成链路 → 关键 Prompt → 可复用套路。","link":"/cases/","linkText":"进入板块"}]},"headers":[],"relativePath":"index.md","filePath":"index.md","lastUpdated":1786503105000}'),s={name:"index.md"};function i(l,t,n,d,p,h){return a(),r("div",null,[...t[0]||(t[0]=[o('<h2 id="这个知识库解决什么问题" tabindex="-1">这个知识库解决什么问题 <a class="header-anchor" href="#这个知识库解决什么问题" aria-label="Permalink to &quot;这个知识库解决什么问题&quot;">​</a></h2><p>AI 生成广告素材，最容易踩的坑不是「不会用工具」，而是三件事：</p><ol><li><strong>拿到工具却不知道从哪下嘴</strong> —— 会写 Prompt，但不知道一支广告该拆成几个镜头、每个镜头该给什么描述。</li><li><strong>出图很惊艳，成片很业余</strong> —— 单张素材质量高，串成 30 秒却前后不连、风格漂移、节奏散乱。</li><li><strong>每次都从零开始</strong> —— 上次调通的参数、试出来的句式，两周后就想不起来了。</li></ol><p>所以这里的组织方式是<strong>倒过来的</strong>：不从「工具怎么用」讲起，而从「一支广告怎么做出来」讲起，工具只是链路上的零件。</p><h2 id="三条推荐路径" tabindex="-1">三条推荐路径 <a class="header-anchor" href="#三条推荐路径" aria-label="Permalink to &quot;三条推荐路径&quot;">​</a></h2><table tabindex="0"><thead><tr><th>你的处境</th><th>建议路线</th></tr></thead><tbody><tr><td>完全没做过，想先看懂全貌</td><td><a href="/guide/landscape">AI 创意广告全景</a> → <a href="/method/workflow-sop">完整链路 SOP</a> → <a href="/cases/case-01-beverage-tvc">案例 01</a></td></tr><tr><td>手上有活，今天就要出图</td><td><a href="/prompts/structure">Prompt 结构通法</a> → <a href="/prompts/product-still">产品静物 / 电商主图</a></td></tr><tr><td>要做视频，卡在分镜</td><td><a href="/method/storyboard">分镜设计</a> → <a href="/prompts/video-storyboard">短视频分镜脚本</a></td></tr></tbody></table><h2 id="关于内容的两点说明" tabindex="-1">关于内容的两点说明 <a class="header-anchor" href="#关于内容的两点说明" aria-label="Permalink to &quot;关于内容的两点说明&quot;">​</a></h2><p><strong>工具信息会过时。</strong> 价格、参数上限、功能开关这类信息变动极快，本站一律不写死具体数字，只写工具的<strong>定位</strong>与<strong>适用场景</strong>——这部分相对稳定。真要下单前，请以官网为准。</p><p><strong>这是一份活文档。</strong> 「待补充」的条目是有意留着的坑，配了写作模板，遇到新经验就往里填。见 <a href="/templates/">写作模板</a>。</p>',9)])])}const f=e(s,[["render",i]]);export{c as __pageData,f as default};
